-- Financial statement account lines must use closing/as-of-end balances for balance-sheet accounts.
-- Income-statement accounts remain limited to the selected reporting period.
create or replace function public.get_financial_statement_account_lines_core(p_organization_id uuid,p_start_date date,p_end_date date,p_branch_id uuid default null,p_department_id uuid default null,p_cost_center_id uuid default null,p_region_id uuid default null,p_product_id uuid default null,p_project_id uuid default null,p_account_id uuid default null) returns jsonb language plpgsql security definer set search_path to '' as $function$
declare v_user_id uuid:=auth.uid(); r jsonb;
begin
 if v_user_id is null then raise exception 'Authentication required'; end if;
 if not exists(select 1 from public.organization_members om where om.organization_id=p_organization_id and om.user_id=v_user_id) then raise exception 'Organization access required'; end if;
 if not (public.has_org_permission(p_organization_id,'screen.financial_statements.view') or public.has_org_permission(p_organization_id,'statements.view') or public.has_org_permission(p_organization_id,'view')) then raise exception 'Financial statements view permission required'; end if;
 if p_start_date is null or p_end_date is null or p_start_date>p_end_date then raise exception 'Invalid date range'; end if;
 with recursive scope_flags as materialized (select coalesce(array_agg(s.scope_id) filter(where s.scope_type='legal_entity'),'{}'::uuid[]) legal_entities,coalesce(array_agg(s.scope_id) filter(where s.scope_type='branch'),'{}'::uuid[]) branches,coalesce(array_agg(s.scope_id) filter(where s.scope_type='department'),'{}'::uuid[]) departments,coalesce(array_agg(s.scope_id) filter(where s.scope_type='cost_center'),'{}'::uuid[]) cost_centers,coalesce(array_agg(s.scope_id) filter(where s.scope_type='region'),'{}'::uuid[]) regions,coalesce(array_agg(s.scope_id) filter(where s.scope_type='product'),'{}'::uuid[]) products,coalesce(array_agg(s.scope_id) filter(where s.scope_type='project'),'{}'::uuid[]) projects,count(*)>0 has_any from public.organization_member_scopes s where s.organization_id=p_organization_id and s.user_id=v_user_id), facts as materialized (select f.account_id,f.debit_minor,f.credit_minor,f.transaction_date,f.legal_entity_id,f.branch_id,f.department_id,f.cost_center_id,f.region_id,f.product_id,f.project_id from public.financial_facts f cross join scope_flags sf where f.organization_id=p_organization_id and f.fact_type='actual' and f.status='published' and f.transaction_date<=p_end_date and (p_branch_id is null or f.branch_id=p_branch_id) and (p_department_id is null or f.department_id=p_department_id) and (p_cost_center_id is null or f.cost_center_id=p_cost_center_id) and (p_region_id is null or f.region_id=p_region_id) and (p_product_id is null or f.product_id=p_product_id) and (p_project_id is null or f.project_id=p_project_id) and (p_account_id is null or f.account_id=p_account_id) and (not sf.has_any or cardinality(sf.legal_entities)=0 or f.legal_entity_id is null or f.legal_entity_id=any(sf.legal_entities)) and (not sf.has_any or cardinality(sf.branches)=0 or f.branch_id is null or f.branch_id=any(sf.branches)) and (not sf.has_any or cardinality(sf.departments)=0 or f.department_id is null or f.department_id=any(sf.departments)) and (not sf.has_any or cardinality(sf.cost_centers)=0 or f.cost_center_id is null or f.cost_center_id=any(sf.cost_centers)) and (not sf.has_any or cardinality(sf.regions)=0 or f.region_id is null or f.region_id=any(sf.regions)) and (not sf.has_any or cardinality(sf.products)=0 or f.product_id is null or f.product_id=any(sf.products)) and (not sf.has_any or cardinality(sf.projects)=0 or f.project_id is null or f.project_id=any(sf.projects))), raw as (select a.id,a.code,a.name,a.account_type,a.statement_type,a.statement_section,a.statement_subclassification,a.parent_account_id,a.is_contra,coalesce(sum(case when a.statement_type='balance_sheet' then f.debit_minor-f.credit_minor when f.transaction_date between p_start_date and p_end_date then f.debit_minor-f.credit_minor else 0 end),0)::bigint raw_balance from public.accounts a left join facts f on f.account_id=a.id where a.organization_id=p_organization_id and (a.statement_type in ('balance_sheet','income_statement') or a.statement_subclassification='other_comprehensive_income') group by a.id,a.code,a.name,a.account_type,a.statement_type,a.statement_section,a.statement_subclassification,a.parent_account_id,a.is_contra), normalized as (select *,case when statement_type='income_statement' and statement_subclassification in ('revenue','other_income') then -raw_balance else raw_balance end * case when is_contra then -1 else 1 end balance from raw), roll as (select id ancestor_id,id descendant_id,balance from normalized union all select p.parent_account_id,r.descendant_id,r.balance from roll r join normalized p on p.id=r.ancestor_id where p.parent_account_id is not null), rolled as (select ancestor_id,sum(balance)::bigint balance from roll group by ancestor_id), lines as (select n.id,n.code,n.name,n.account_type,n.statement_type,n.statement_section,n.statement_subclassification,n.parent_account_id,n.is_contra,n.balance own_balance,coalesce(r.balance,0)::bigint balance from normalized n left join rolled r on r.ancestor_id=n.id), tree as (select l.id,l.parent_account_id,l.code,l.name,l.account_type,l.statement_type,l.statement_section,l.statement_subclassification,l.is_contra,l.own_balance,l.balance,0::int depth,array[l.id]::uuid[] hierarchy_ids,array[l.code]::text[] hierarchy_sort from lines l where l.parent_account_id is null union all select c.id,c.parent_account_id,c.code,c.name,c.account_type,c.statement_type,c.statement_section,c.statement_subclassification,c.is_contra,c.own_balance,c.balance,t.depth+1,t.hierarchy_ids||c.id,t.hierarchy_sort||c.code from tree t join lines c on c.parent_account_id=t.id), shaped as (select t.*,exists(select 1 from lines c where c.parent_account_id=t.id) has_children from tree t) select coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'account_type',account_type,'statement_type',statement_type,'statement_section',statement_section,'statement_subclassification',statement_subclassification,'parent_account_id',parent_account_id,'is_contra',is_contra,'own_balance',own_balance,'balance',balance,'depth',depth,'has_children',has_children) order by hierarchy_sort),'[]'::jsonb) into r from shaped; return r;
end;$function$;
